M["modules/combat.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Combat: knife aura, kill all, sheriff auto-shot v0.1.0.
--
-- All of this uses the game's OWN knife/gun remotes — the same replication
-- path a legitimate stab takes (verified across working hubs):
--   * stab:  Character.Knife.Events.KnifeStabbed:FireServer()
--            Character.Knife.Events.HandleTouched:FireServer(targetRoot)
--   * touch fallback: firetouchinterest(Handle, targetRoot, 0/1)
--   * sheriff shot: Gun.KnifeLocal.CreateBeam.RemoteFunction:InvokeServer(
--            1, targetPosition, "AH2") — the SERVER does the hit test.
-- Requirements: murderer needs the Knife in Character (server enforces);
-- sheriff needs the Gun. These are the highest-report features — every call
-- is humanized and rate-capped, and the UI marks them as risky.

local Players = game:GetService("Players")

local Combat = {}

Combat.AuraEnabled = false
Combat.SheriffAutoEnabled = false
Combat.LastKillName = "—"
Combat.KillCount = 0
Combat.Status = "выключено"
Combat.Debug = false
Combat.OnNotify = nil

local ConfigRef = nil
local RolesRef = nil
local StealthRef = nil

local localPlayer = Players.LocalPlayer
local auraRunning = false
local sheriffRunning = false
local lastAuraAt = 0
local lastShotAt = 0

local function note(...)
    if Combat.Debug then print("[mh combat]", ...) end
end

local function jitter(value)
    if ConfigRef and ConfigRef.Settings.HumanizeDelays then
        return value * (0.8 + math.random() * 0.5)
    end
    return value
end

local function getCharacterParts()
    local character = localPlayer.Character
    if not character then return nil, nil end
    return character, character:FindFirstChild("HumanoidRootPart")
end

local function findTool(character, name)
    if character and character:FindFirstChild(name) then
        return character:FindFirstChild(name)
    end
    local backpack = localPlayer:FindFirstChildOfClass("Backpack")
    if backpack and backpack:FindFirstChild(name) then
        pcall(function() character.Humanoid:EquipTool(backpack:FindFirstChild(name)) end)
        return character and character:FindFirstChild(name)
    end
    return nil
end

local function aliveTargetRoot(targetPlayer)
    local character = targetPlayer.Character
    if not character then return nil end
    local humanoid = character:FindFirstChildOfClass("Humanoid")
    local root = character:FindFirstChild("HumanoidRootPart")
    if humanoid and humanoid.Health > 0 and root then
        return root
    end
    return nil
end

local function nearbyTargets(radius, maxCount)
    local _, myRoot = getCharacterParts()
    if not myRoot then return {} end
    local list = {}
    for _, player in ipairs(Players:GetPlayers()) do
        if player ~= localPlayer and RolesRef.IsAlive(player.Name) then
            local root = aliveTargetRoot(player)
            if root and (root.Position - myRoot.Position).Magnitude <= radius then
                list[#list + 1] = { Player = player, Root = root }
                if maxCount and #list >= maxCount then break end
            end
        end
    end
    return list
end

---------------------------------------------------------------------
-- Knife stab replication (murderer only)
---------------------------------------------------------------------

local function stabTarget(knife, targetRoot)
    local ok = pcall(function()
        local events = knife:FindFirstChild("Events")
        if events then
            local stabbed = events:FindFirstChild("KnifeStabbed")
            local touched = events:FindFirstChild("HandleTouched")
            if stabbed then stabbed:FireServer() end
            if touched and targetRoot then touched:FireServer(targetRoot) end
            return
        end
        -- Older builds: Knife.Stab with Down/Up.
        local stab = knife:FindFirstChild("Stab")
        if stab then
            stab:FireServer(targetRoot and targetRoot.Position or "Down")
        end
    end)
    -- Physical touch fallback: replicate the handle touching the victim.
    if ok == nil or ok then
        pcall(function()
            local handle = knife:FindFirstChild("Handle") or knife:FindFirstChildWhichIsA("BasePart")
            if handle and type(firetouchinterest) == "function" then
                firetouchinterest(handle, targetRoot, 0)
                firetouchinterest(handle, targetRoot, 1)
            end
        end)
    end
end

---------------------------------------------------------------------
-- Aura loop
---------------------------------------------------------------------

local function auraLoop()
    while auraRunning do
        local settings = ConfigRef.Settings
        if not RolesRef.LocalIsMurderer() then
            Combat.Status = "нужна роль МАНЬЯК"
        else
            local character, _ = getCharacterParts()
            local knife = character and findTool(character, "Knife")
            if not knife then
                Combat.Status = "нож не найден"
            else
                local targets = nearbyTargets(settings.AuraRadius or 14, 3)
                if #targets == 0 then
                    Combat.Status = "целей рядом нет"
                else
                    for _, target in ipairs(targets) do
                        stabTarget(knife, target.Root)
                        Combat.KillCount = Combat.KillCount + 1
                        Combat.LastKillName = target.Player.Name
                        Combat.Status = "аура: " .. target.Player.Name
                        task.wait(jitter(math.max(0.5, settings.AuraDelay or 1.0)))
                    end
                end
            end
        end
        task.wait(jitter(0.4))
    end
end

---------------------------------------------------------------------
-- Sheriff auto-shot
---------------------------------------------------------------------

local function trySheriffShot()
    local settings = ConfigRef.Settings
    if not RolesRef.LocalIsSheriff() then
        Combat.Status = "нужна роль ШЕРИФ/ГЕРОЙ"
        return
    end
    local character, _ = getCharacterParts()
    local gun = character and findTool(character, "Gun")
    if not gun then
        Combat.Status = "пистолет не найден"
        return
    end

    local murderers = RolesRef.FindByRole("Murderer")
    for _, name in ipairs(murderers) do
        local target = Players:FindFirstChild(name)
        local root = target and aliveTargetRoot(target)
        if root then
            local _, myRoot = getCharacterParts()
            if myRoot and (root.Position - myRoot.Position).Magnitude <= (settings.SheriffRange or 300) then
                -- LOS check so we do not shoot through walls blindly.
                local camera = workspace.CurrentCamera
                local origin = myRoot.Position
                local direction = root.Position - origin
                local params = RaycastParams.new()
                params.FilterType = Enum.RaycastFilterType.Exclude
                params.FilterDescendantsInstances = { localPlayer.Character }
                local hit = workspace:Raycast(origin, direction, params)
                local visible = hit and hit.Instance and hit.Instance:IsDescendantOf(target.Character)
                if visible then
                    local ok = pcall(function()
                        local beamLocal = gun:FindFirstChild("KnifeLocal")
                        local createBeam = beamLocal and beamLocal:FindFirstChild("CreateBeam")
                        local remote = createBeam and createBeam:FindFirstChildOfClass("RemoteFunction")
                        if remote then
                            remote:InvokeServer(1, root.Position, "AH2")
                        else
                            local shoot = gun:FindFirstChild("Shoot")
                            if shoot then
                                shoot:FireServer(CFrame.new(origin), CFrame.new(root.Position))
                            end
                        end
                    end)
                    if ok then
                        Combat.LastKillName = name
                        Combat.KillCount = Combat.KillCount + 1
                        Combat.Status = "выстрел: " .. name
                        if Combat.OnNotify then pcall(Combat.OnNotify, "Выстрел в маньяка: " .. name) end
                    end
                    lastShotAt = os.clock()
                    return
                end
            end
        end
    end
end

local function sheriffLoop()
    while sheriffRunning do
        local ok, err = pcall(trySheriffShot)
        if not ok then note("sheriff: " .. tostring(err)) end
        task.wait(jitter(1.2))
    end
end

---------------------------------------------------------------------
-- Kill all (manual button, murderer only)
---------------------------------------------------------------------

function Combat.KillAll()
    if not RolesRef.LocalIsMurderer() then
        return false, "нужна роль МАНЬЯК"
    end
    local character, _ = getCharacterParts()
    local knife = character and findTool(character, "Knife")
    if not knife then
        return false, "нож не найден"
    end
    local targets = nearbyTargets(60, 12)
    if #targets == 0 then
        return false, "никого в радиусе 60"
    end
    task.spawn(function()
        for _, target in ipairs(targets) do
            local fresh = getCharacterParts()
            local freshKnife = fresh and findTool(fresh, "Knife")
            if freshKnife then
                stabTarget(freshKnife, target.Root)
                Combat.KillCount = Combat.KillCount + 1
                Combat.LastKillName = target.Player.Name
            end
            task.wait(jitter(0.45))
        end
        Combat.Status = "kill all: " .. tostring(#targets) .. " целей"
    end)
    return true, "целей: " .. tostring(#targets)
end

---------------------------------------------------------------------
-- Public API
---------------------------------------------------------------------

function Combat.SetAura(value)
    Combat.AuraEnabled = value and true or false
    ConfigRef.Settings.KnifeAura = Combat.AuraEnabled
    if value and not auraRunning then
        auraRunning = true
        task.spawn(auraLoop)
    elseif not value then
        auraRunning = false
        Combat.Status = "выключено"
    end
end

function Combat.SetSheriffAuto(value)
    Combat.SheriffAutoEnabled = value and true or false
    ConfigRef.Settings.SheriffAuto = Combat.SheriffAutoEnabled
    if value and not sheriffRunning then
        sheriffRunning = true
        task.spawn(sheriffLoop)
    elseif not value then
        sheriffRunning = false
        Combat.Status = "выключено"
    end
end

function Combat.Configure(config, roles, stealth)
    ConfigRef = config
    RolesRef = roles
    StealthRef = stealth
    Combat.Debug = config.Settings.DebugLogs == true
end

function Combat.Destroy()
    auraRunning = false
    sheriffRunning = false
end

return Combat
]====]

M["modules/movement.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Movement & teleports v0.1.0.
--
-- MM2 has no known movement anticheat (9 public hubs use WalkSpeed 18-50,
-- noclip via Humanoid:ChangeState(11), teleports freely). We still keep the
-- sane defaults: speed slider capped at 50, teleports through glide by
-- default (CALM doctrine), CharacterAdded re-apply.

local Players = game:GetService("Players")
local UserInputService = game:GetService("UserInputService")
local RunService = game:GetService("RunService")

local Movement = {}

Movement.AntiAFKEnabled = false
Movement.Debug = false
Movement.OnNotify = nil

local ConfigRef = nil
local StealthRef = nil

local connections = {}
local noclipRunning = false
local infJumpRunning = false
local clickTPActive = false
local antiAFKConnection = nil
local clickTPConnection = nil
local localPlayer = Players.LocalPlayer

local function note(...)
    if Movement.Debug then print("[mh move]", ...) end
end

local function getCharacterParts()
    local character = localPlayer and localPlayer.Character
    if not character then return nil, nil end
    return character:FindFirstChildOfClass("Humanoid"), character:FindFirstChild("HumanoidRootPart")
end

---------------------------------------------------------------------
-- Speed / jump
---------------------------------------------------------------------

function Movement.ApplySpeed(value)
    local humanoid = getCharacterParts()
    if humanoid and value and value > 0 then
        pcall(function() humanoid.WalkSpeed = value end)
    end
end

function Movement.ApplyJump(value)
    local humanoid = getCharacterParts()
    if humanoid and value and value > 0 then
        pcall(function()
            humanoid.UseJumpPower = true
            humanoid.JumpPower = value
        end)
    end
end

---------------------------------------------------------------------
-- Infinite jump
---------------------------------------------------------------------

local function setInfJump(value)
    infJumpRunning = value and true or false
    if value then
        task.spawn(function()
            while infJumpRunning do
                task.wait(0.05)
                if UserInputService.JumpRequest then
                    local humanoid = getCharacterParts()
                    if humanoid then pcall(function() humanoid:ChangeState(Enum.HumanoidStateType.Jumping) end) end
                end
            end
        end)
    end
end

---------------------------------------------------------------------
-- Noclip
---------------------------------------------------------------------

local function setNoclip(value)
    noclipRunning = value and true or false
    if value then
        task.spawn(function()
            while noclipRunning do
                local _, root = getCharacterParts()
                if root then
                    pcall(function()
                        for _, part in ipairs(root.Parent:GetDescendants()) do
                            if part:IsA("BasePart") and part.CanCollide then
                                part.CanCollide = false
                            end
                        end
                    end)
                end
                RunService.Heartbeat:Wait()
            end
            -- restore collisions on disable
            local _, root = getCharacterParts()
            if root and root.Parent then
                pcall(function()
                    for _, part in ipairs(root.Parent:GetDescendants()) do
                        if part:IsA("BasePart") then part.CanCollide = true end
                    end
                    root.Parent.PrimaryPart = root
                    root.CanCollide = true
                end)
            end
        end)
    end
end

---------------------------------------------------------------------
-- Click TP (glide to clicked point)
---------------------------------------------------------------------

local function setClickTP(value)
    clickTPActive = value and true or false
    if value then
        if clickTPConnection then
            pcall(function() clickTPConnection:Disconnect() end)
            clickTPConnection = nil
        end
        clickTPConnection = UserInputService.InputBegan:Connect(function(input, processed)
            if not clickTPActive or processed then return end
            if input.UserInputType ~= Enum.UserInputType.MouseButton1 and input.UserInputType ~= Enum.UserInputType.Touch then
                return
            end
            local camera = workspace.CurrentCamera
            if not camera then return end
            local ray = camera:ViewportPointToRay(input.Position.X, input.Position.Y)
            local params = RaycastParams.new()
            params.FilterType = Enum.RaycastFilterType.Exclude
            local character = localPlayer and localPlayer.Character
            if character then params.FilterDescendantsInstances = { character } end
            local result = workspace:Raycast(ray.Origin, ray.Direction * 1000, params)
            if result and StealthRef and StealthRef.GlideTo then
                note("clickTP -> " .. tostring(result.Position))
                task.spawn(function()
                    StealthRef.GlideTo(result.Position + Vector3.new(0, 2, 0), {})
                end)
            end
        end)
    end
end

---------------------------------------------------------------------
-- Public toggles (used by features.lua)
---------------------------------------------------------------------

function Movement.SetInfJump(value)
    if ConfigRef then ConfigRef.Settings.InfiniteJump = value and true or false end
    setInfJump(value and true or false)
end

function Movement.SetNoclip(value)
    if ConfigRef then ConfigRef.Settings.Noclip = value and true or false end
    setNoclip(value and true or false)
end

function Movement.SetClickTP(value)
    if ConfigRef then ConfigRef.Settings.ClickTP = value and true or false end
    setClickTP(value and true or false)
end

---------------------------------------------------------------------
-- Teleports
---------------------------------------------------------------------

function Movement.ToLobby()
    if StealthRef and StealthRef.GlideTo then
        task.spawn(function()
            local position = Vector3.new(14.72, 506.2, -61.29)
            local world = Movement.WorldRef
            if world and world.GetLobbyPosition then
                local found = world.GetLobbyPosition()
                if found then position = found end
            end
            StealthRef.GlideTo(position, { Speed = ConfigRef.Settings.GlideSpeed or 48 })
            if Movement.OnNotify then pcall(Movement.OnNotify, "Телепорт в лобби выполнен") end
        end)
        return true
    end
    return false
end

function Movement.ToMap()
    -- WorldRef is injected to avoid a circular dependency.
    local world = Movement.WorldRef
    if not world then return false end
    local position = world.GetMapSpawn()
    if not position then return false end
    task.spawn(function()
        if StealthRef and StealthRef.GlideTo then
            StealthRef.GlideTo(position, { Speed = ConfigRef.Settings.GlideSpeed or 48 })
        else
            local _, root = getCharacterParts()
            if root then root.CFrame = CFrame.new(position) end
        end
        if Movement.OnNotify then pcall(Movement.OnNotify, "Телепорт на карту выполнен") end
    end)
    return true
end

function Movement.AboveMap()
    local world = Movement.WorldRef
    if not world then return false end
    local center = world.GetMapCenter()
    if not center then return false end
    local target = center + Vector3.new(0, 120, 0)
    task.spawn(function()
        local _, root = getCharacterParts()
        if not root then return end
        if StealthRef and StealthRef.GlideTo then
            StealthRef.GlideTo(target, { Speed = 90, Height = 0 })
        else
            root.CFrame = CFrame.new(target)
        end
        task.wait(0.4)
    end)
    return true
end

function Movement.ToPlayer(playerName)
    local target = nil
    for _, player in ipairs(Players:GetPlayers()) do
        if string.lower(player.Name) == string.lower(playerName or "") then target = player end
    end
    if not target or not target.Character then return false end
    local root = target.Character:FindFirstChild("HumanoidRootPart")
    if not root then return false end
    task.spawn(function()
        if StealthRef and StealthRef.GlideTo then
            StealthRef.GlideTo(root.Position, {})
        else
            local _, myRoot = getCharacterParts()
            if myRoot then myRoot.CFrame = root.CFrame * CFrame.new(0, 0, 3) end
        end
    end)
    return true
end

---------------------------------------------------------------------
-- Anti-AFK
---------------------------------------------------------------------

function Movement.SetAntiAFK(value)
    Movement.AntiAFKEnabled = value and true or false
    if value then
        local virtualUser = game:GetService("VirtualUser")
        antiAFKConnection = localPlayer.Idled:Connect(function()
            pcall(function()
                virtualUser:CaptureController()
                virtualUser:ClickButton2(Vector2.new())
            end)
            note("anti-afk pulse")
        end)
        connections[#connections + 1] = antiAFKConnection
    elseif antiAFKConnection then
        pcall(function() antiAFKConnection:Disconnect() end)
        antiAFKConnection = nil
    end
end

---------------------------------------------------------------------
-- Lifecycle
---------------------------------------------------------------------

function Movement.Configure(config, stealth)
    ConfigRef = config
    StealthRef = stealth
    Movement.Debug = config.Settings.DebugLogs == true

    -- Re-apply speed/jump on respawn.
    connections[#connections + 1] = localPlayer.CharacterAdded:Connect(function(character)
        local humanoid = character:WaitForChild("Humanoid", 5)
        if humanoid then
            task.wait(0.3)
            Movement.ApplySpeed(ConfigRef.Settings.WalkSpeed)
            Movement.ApplyJump(ConfigRef.Settings.JumpPower)
        end
    end)
    if localPlayer.Character then
        Movement.ApplySpeed(ConfigRef.Settings.WalkSpeed)
        Movement.ApplyJump(ConfigRef.Settings.JumpPower)
    end
end

function Movement.Destroy()
    noclipRunning = false
    infJumpRunning = false
    clickTPActive = false
    if clickTPConnection then
        pcall(function() clickTPConnection:Disconnect() end)
        clickTPConnection = nil
    end
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    connections = {}
    -- Full reset to vanilla values.
    local humanoid = getCharacterParts()
    if humanoid then
        pcall(function()
            humanoid.WalkSpeed = 16
            humanoid.JumpPower = 50
        end)
    end
end

return Movement
]====]

M["modules/visuals.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Visuals: fullbright, no fog, corpse/barrier cleanup, FPS mode v0.1.0.
--
-- All client-side Lighting tweaks (zero server footprint):
--   * Fullbright: brightness 3, clock 14, ambient light gray, no color shift;
--   * NoFog: FogEnd 100000, FogStart 0, expose desaturated fog color;
--   * corpses: MM2 ragdolls are workspace children named "Raggy";
--   * barriers: Model "GlitchProof" (map edge walls) — removal is client-side
--     only and harmless to the server;
--   * FPS mode: kill particles/sparkles/shadows for weak phones.

local Lighting = game:GetService("Lighting")
local Workspace = game:GetService("Workspace")

local Visuals = {}

Visuals.Debug = false

local ConfigRef = nil
local connections = {}
local savedLighting = nil
local fullbrightOn = false
local noFogOn = false

local function note(...)
    if Visuals.Debug then print("[mh vis]", ...) end
end

local function snapshotLighting()
    if savedLighting then return end
    savedLighting = {
        Brightness = Lighting.Brightness,
        ClockTime = Lighting.ClockTime,
        Ambient = Lighting.Ambient,
        OutdoorAmbient = Lighting.OutdoorAmbient,
        GlobalShadows = Lighting.GlobalShadows,
        FogEnd = Lighting.FogEnd,
        FogStart = Lighting.FogStart,
        FogColor = Lighting.FogColor,
    }
end

function Visuals.SetFullbright(value)
    fullbrightOn = value and true or false
    if value then
        snapshotLighting()
        pcall(function()
            Lighting.Brightness = 3
            Lighting.ClockTime = 14
            Lighting.Ambient = Color3.fromRGB(178, 178, 178)
            Lighting.OutdoorAmbient = Color3.fromRGB(178, 178, 178)
            Lighting.GlobalShadows = false
        end)
    else
        if savedLighting then
            pcall(function()
                Lighting.Brightness = savedLighting.Brightness
                Lighting.ClockTime = savedLighting.ClockTime
                Lighting.Ambient = savedLighting.Ambient
                Lighting.OutdoorAmbient = savedLighting.OutdoorAmbient
                Lighting.GlobalShadows = savedLighting.GlobalShadows
            end)
        end
    end
end

function Visuals.SetNoFog(value)
    noFogOn = value and true or false
    if value then
        snapshotLighting()
        pcall(function()
            Lighting.FogEnd = 100000
            Lighting.FogStart = 0
        end)
    else
        if savedLighting then
            pcall(function()
                Lighting.FogEnd = savedLighting.FogEnd
                Lighting.FogStart = savedLighting.FogStart
                Lighting.FogColor = savedLighting.FogColor
            end)
        end
    end
end

---------------------------------------------------------------------
-- Corpse & barrier cleanup
---------------------------------------------------------------------

local function sweepNamed(parent, name)
    local count = 0
    pcall(function()
        for _, child in ipairs(parent:GetChildren()) do
            if child.Name == name then
                child:Destroy()
                count = count + 1
            end
        end
    end)
    return count
end

function Visuals.SetRemoveRagdolls(value)
    ConfigRef.Settings.RemoveRagdolls = value and true or false
    if value then
        sweepNamed(Workspace, "Raggy")
        connections[#connections + 1] = Workspace.ChildAdded:Connect(function(child)
            if ConfigRef.Settings.RemoveRagdolls and child.Name == "Raggy" then
                task.wait(0.5)
                pcall(function() child:Destroy() end)
            end
        end)
    else
        for _, connection in ipairs(connections) do connection:Disconnect() end
        connections = {}
    end
end

function Visuals.SetRemoveBarriers(value)
    ConfigRef.Settings.RemoveBarriers = value and true or false
    if value then
        pcall(function()
            for _, descendant in ipairs(Workspace:GetDescendants()) do
                if descendant.Name == "GlitchProof" then
                    descendant:Destroy()
                end
            end
        end)
        note("barriers removed")
    end
end

---------------------------------------------------------------------
-- FPS mode
---------------------------------------------------------------------

function Visuals.SetFpsMode(value)
    pcall(function()
        if value then
            Lighting.GlobalShadows = false
            Lighting.FogEnd = 950
            settings().Rendering.QualityLevel = Enum.QualityLevel.Level01
        else
            if savedLighting then
                Lighting.GlobalShadows = savedLighting.GlobalShadows
                Lighting.FogEnd = savedLighting.FogEnd
            end
            settings().Rendering.QualityLevel = Enum.QualityLevel.Automatic
        end
    end)
end

---------------------------------------------------------------------
-- Lifecycle
---------------------------------------------------------------------

function Visuals.Configure(config)
    ConfigRef = config
    Visuals.Debug = config.Settings.DebugLogs == true
end

function Visuals.Destroy()
    for _, connection in ipairs(connections) do
        pcall(function() connection:Disconnect() end)
    end
    connections = {}
    Visuals.SetFullbright(false)
    Visuals.SetNoFog(false)
    Visuals.SetFpsMode(false)
end

return Visuals
]====]

M["modules/features.lua"] = [====[
-- MilfaCheatHUB • Murder Mystery 2
-- Feature wiring v0.1.0. Six tabs: ИГРОКИ / АВТО / ПЕРСОНАЖ / ВИЗУАЛ / БОЙ / СИСТЕМА.
-- 40+ controls; risky combat features are labeled and rate-capped.

local Players = game:GetService("Players")
local localPlayer = Players.LocalPlayer

local Features = {}
Features.__index = Features

function Features.new(config, ui, roles, network, world, esp, farm, combat, movement, visuals, alive, stealth)
    local self = setmetatable({}, Features)
    self.Config = config
    self.UI = ui
    self.Roles = roles
    self.Network = network
    self.World = world
    self.ESP = esp
    self.Farm = farm
    self.Combat = combat
    self.Movement = movement
    self.Visuals = visuals
    self.Alive = alive
    self.Stealth = stealth
    self.Running = false
    self.LastGrabAt = 0
    return self
end

function Features:Build()
    local colors = self.Config.Colors
    local settings = self.Config.Settings

    local playersTab = self.UI:CreateTab("Игроки", "ESP", colors.ESP)
    local autoTab = self.UI:CreateTab("Авто", "BOT", colors.Combat)
    local playerTab = self.UI:CreateTab("Персонаж", "PLR", colors.Player)
    local visualTab = self.UI:CreateTab("Визуал", "VIS", colors.World)
    local combatTab = self.UI:CreateTab("Бой", "HIT", colors.Combat)
    local systemTab = self.UI:CreateTab("Система", "SYS", colors.Misc)

    -- ============================== ИГРОКИ ==============================
    self.UI:AddHeading(playersTab, "Роли (видно до ножа)")
    self.RoleStatus = self.UI:AddText(playersTab, "Кто есть кто", "Первый опрос — после открытия GUI")
    -- ESP alerts (murderer nearby / gun dropped) surface on the status card.
    self.ESP.OnAlert = function(message)
        pcall(function() self.RoleStatus:Set(message) end)
    end
    self.UI:AddButton(playersTab, "Обновить роли сейчас", function()
        pcall(function() self.Roles.Refresh() end)
        self:UpdateRoleStatus()
    end)
    self.UI:AddSection(playersTab, "ESP игроков")
    self.UI:AddToggle(playersTab, "Включить ESP игроков", settings.PlayerESP, function(value)
        self.ESP.SetEnabled(value)
    end)
    self.UI:AddToggle(playersTab, "Подсветка сквозь стены (Highlight)", settings.EspHighlight, function(value)
        settings.EspHighlight = value
    end)
    self.UI:AddToggle(playersTab, "Показывать роль", settings.EspShowRole, function(value)
        settings.EspShowRole = value
    end)
    self.UI:AddToggle(playersTab, "Показывать дистанцию", settings.EspShowDistance, function(value)
        settings.EspShowDistance = value
    end)
    self.UI:AddToggle(playersTab, "Только цели (скрыть мирных)", settings.EspOnlyTargets, function(value)
        settings.EspOnlyTargets = value
    end)
    self.UI:AddSlider(playersTab, "Макс. дистанция ESP", 100, 2000, settings.EspMaxDistance, " м", function(value)
        settings.EspMaxDistance = value
    end)
    self.UI:AddSlider(playersTab, "Частота обновления", 0.5, 3, settings.RefreshSeconds, " с", function(value)
        settings.RefreshSeconds = value
    end)
    self.UI:AddSection(playersTab, "Алерты")
    self.UI:AddToggle(playersTab, "Алерты «МАНЬЯК рядом»", settings.MurderAlert, function(value)
        settings.MurderAlert = value
    end)
    self.UI:AddSlider(playersTab, "Радиус алерта маньяка", 20, 200, settings.MurderAlertDistance, " м", function(value)
        settings.MurderAlertDistance = value
    end)
    self.UI:AddToggle(playersTab, "Алерты о выпавшем пистолете", settings.GunDropAlert, function(value)
        settings.GunDropAlert = value
    end)
    self.UI:AddToggle(playersTab, "Подсветка GunDrop", settings.GunDropESP, function(value)
        settings.GunDropESP = value
    end)
    self.UI:AddButton(playersTab, "Телепорт к маньяку", function()
        local list = self.Roles.FindByRole("Murderer")
        if #list > 0 then
            self:GlideToPlayer(list[1])
        else
            self.RoleStatus:Set("маньяк неизвестен — обнови роли")
        end
    end)
    self.UI:AddButton(playersTab, "Телепорт к шерифу", function()
        local list = self.Roles.FindByRole("Sheriff")
        if #list > 0 then
            self:GlideToPlayer(list[1])
        else
            self.RoleStatus:Set("шериф неизвестен — обнови роли")
        end
    end)

    -- ============================== АВТО ==============================
    self.UI:AddHeading(autoTab, "Фарм монет")
    self.FarmStatus = self.UI:AddText(autoTab, "Состояние фарма", "выключено")
    self.UI:AddToggle(autoTab, "Магнит монет (сбор без движения)", settings.CoinMagnet, function(value)
        self.Farm.SetMagnet(value)
    end)
    self.UI:AddSlider(autoTab, "Радиус магнита", 8, 60, settings.MagnetRadius, " м", function(value)
        settings.MagnetRadius = value
    end)
    self.UI:AddToggle(autoTab, "Автофарм (обход монет)", settings.CoinFarm, function(value)
        self.Farm.SetFarm(value)
    end)
    self.UI:AddDropdown(autoTab, "Режим фарма", { "Teleport", "Smooth", "Walk" }, settings.FarmMode, function(option)
        settings.FarmMode = option
    end)
    self.UI:AddSlider(autoTab, "Задержка фарма", 0.3, 3, settings.FarmDelay, " с", function(value)
        settings.FarmDelay = value
    end)
    self.UI:AddToggle(autoTab, "Стоп при полной сумке", settings.StopOnFull, function(value)
        settings.StopOnFull = value
    end)
    self.UI:AddToggle(autoTab, "Уходить в лобби при полной сумке", settings.LobbyOnFull, function(value)
        settings.LobbyOnFull = value
    end)
    self.UI:AddToggle(autoTab, "Собирать монеты и в лобби", settings.FarmLobbyCoins, function(value)
        settings.FarmLobbyCoins = value
    end)
    self.UI:AddButton(autoTab, "Сбросить счётчик собранных", function()
        self.Farm.CoinsCollected = 0
    end)
    self.UI:AddSection(autoTab, "Помощники раунда")
    self.UI:AddToggle(autoTab, "Автоподбор пистолета (GunDrop)", settings.GunGrabber, function(value)
        settings.GunGrabber = value
    end)
    self.UI:AddText(autoTab, "Как работает подбор", "Глайд к выпавшему GunDrop, потом обратно. Маньяк поднять пистолет не может (сервер).")
    self.UI:AddToggle(autoTab, "Anti-AFK", settings.AntiAFK, function(value)
        self.Movement.SetAntiAFK(value)
    end)

    -- ============================== ПЕРСОНАЖ ==============================
    self.UI:AddHeading(playerTab, "Движение")
    self.UI:AddSlider(playerTab, "Скорость (безопасно до 50)", 16, 50, settings.WalkSpeed, "", function(value)
        settings.WalkSpeed = value
        self.Movement.ApplySpeed(value)
    end)
    self.UI:AddButton(playerTab, "Сбросить скорость", function()
        settings.WalkSpeed = 16
        self.Movement.ApplySpeed(16)
    end)
    self.UI:AddSlider(playerTab, "Прыжок", 50, 120, settings.JumpPower, "", function(value)
        settings.JumpPower = value
        self.Movement.ApplyJump(value)
    end)
    self.UI:AddToggle(playerTab, "Бесконечный прыжок", settings.InfiniteJump, function(value)
        settings.InfiniteJump = value
        self.Movement.SetInfJump(value)
    end)
    self.UI:AddToggle(playerTab, "Noclip (сквозь стены)", settings.Noclip, function(value)
        settings.Noclip = value
        self.Movement.SetNoclip(value)
    end)
    self.UI:AddToggle(playerTab, "Клик-телепорт (glide к точке)", settings.ClickTP, function(value)
        settings.ClickTP = value
        self.Movement.SetClickTP(value)
    end)
    self.UI:AddSection(playerTab, "Телепорты")
    self.UI:AddButton(playerTab, "В лобби", function()
        self.Movement.ToLobby()
    end)
    self.UI:AddButton(playerTab, "На карту (спавн)", function()
        if not self.Movement.ToMap() and self.FarmStatus then
            self.FarmStatus:Set("карта не найдена — подойди к карте")
        end
    end)
    self.UI:AddButton(playerTab, "Над картой (обзор)", function()
        self.Movement.AboveMap()
    end)

    -- ============================== ВИЗУАЛ ==============================
    self.UI:AddHeading(visualTab, "Клиентский визуал")
    self.UI:AddToggle(visualTab, "Fullbright (максимальная яркость)", settings.Fullbright, function(value)
        settings.Fullbright = value
        self.Visuals.SetFullbright(value)
    end)
    self.UI:AddToggle(visualTab, "Убрать туман", settings.NoFog, function(value)
        settings.NoFog = value
        self.Visuals.SetNoFog(value)
    end)
    self.UI:AddToggle(visualTab, "Убирать трупы (Raggy)", settings.RemoveRagdolls, function(value)
        self.Visuals.SetRemoveRagdolls(value)
    end)
    self.UI:AddToggle(visualTab, "Убирать барьеры карты (GlitchProof)", settings.RemoveBarriers, function(value)
        self.Visuals.SetRemoveBarriers(value)
    end)
    self.FpsStatus = self.UI:AddText(visualTab, "Производительность", "Обычный режим")
    self.UI:AddToggle(visualTab, "Лёгкий FPS-режим (для телефона)", false, function(value)
        self.Visuals.SetFpsMode(value)
        self.FpsStatus:Set(value and "Тени/эффекты выключены" or "Настройки восстановлены")
    end)

    -- ============================== БОЙ ==============================
    self.UI:AddHeading(combatTab, "Оружие (только у своей роли)")
    self.UI:AddText(combatTab, "Внимание", "Функции боя используют родные ремоуты игры. Максимальный риск репортов от игроков — включай осознанно.")
    self.CombatStatus = self.UI:AddText(combatTab, "Состояние", "выключено")
    self.UI:AddToggle(combatTab, "Нож-аура (автоудар рядом)", settings.KnifeAura, function(value)
        self.Combat.SetAura(value)
    end)
    self.UI:AddSlider(combatTab, "Радиус ауры", 8, 30, settings.AuraRadius, " м", function(value)
        settings.AuraRadius = value
    end)
    self.UI:AddSlider(combatTab, "Пауза между ударами", 0.5, 3, settings.AuraDelay, " с", function(value)
        settings.AuraDelay = value
    end)
    self.UI:AddButton(combatTab, "KILL ALL (все в радиусе 60)", function()
        local ok, message = self.Combat.KillAll()
        if self.CombatStatus then self.CombatStatus:Set(ok and ("KILL ALL: " .. message) or ("ошибка: " .. message)) end
    end)
    self.UI:AddSection(combatTab, "Шериф")
    self.UI:AddToggle(combatTab, "Авто-выстрел в маньяка (шериф/герой)", settings.SheriffAuto, function(value)
        self.Combat.SetSheriffAuto(value)
    end)
    self.UI:AddSlider(combatTab, "Дистанция выстрела", 50, 500, settings.SheriffRange, " м", function(value)
        settings.SheriffRange = value
    end)

    -- ============================== СИСТЕМА ==============================
    self.UI:AddHeading(systemTab, "СТЕЛС CALM (v" .. self.Config.Version .. ")")
    local mountKind = self.Stealth and tostring(self.Stealth.MountKind) or "неизвестно"
    self.StealthStatus = self.UI:AddText(systemTab, "Маунт GUI: " .. mountKind,
        "Скрытый маунт (gethui/CoreGui) — невидим игровым сканерам; в лог при загрузке идёт только номер версии")
    self.UI:AddToggle(systemTab, "Безопасные телепорты (glide)", settings.SafeTeleport, function(value)
        settings.SafeTeleport = value
        if self.Stealth then self.Stealth.SafeTeleport = value end
    end)
    self.UI:AddSlider(systemTab, "Скорость glide", 20, 100, settings.GlideSpeed, " ст/с", function(value)
        settings.GlideSpeed = value
        if self.Stealth then self.Stealth.GlideSpeed = value end
    end)
    self.UI:AddToggle(systemTab, "Человеческие задержки", settings.HumanizeDelays, function(value)
        settings.HumanizeDelays = value
    end)
    self.UI:AddToggle(systemTab, "Подробные логи (держать ВЫКЛ)", settings.DebugLogs, function(value)
        settings.DebugLogs = value
        if self.Stealth then self.Stealth.Debug = value end
        if self.ESP then self.ESP.Debug = value end
        if self.Farm then self.Farm.Debug = value end
        if self.Combat then self.Combat.Debug = value end
    end)
    self.UI:AddButton(systemTab, "PANIC: убрать все следы", function()
        local registry = self.Stealth and self.Stealth.Registry
        if registry and registry.Panic then registry.Panic() end
    end)
    self.UI:AddButton(systemTab, "Диагностика в консоль (F9)", function()
        local registry = self.Stealth and self.Stealth.Registry
        if registry and registry.Diag then
            registry.Diag()
            self.StealthStatus:Set("Диагностика выведена в консоль F9")
        end
    end)
    self.NetworkStatus = self.UI:AddText(systemTab, "Networking", self.Network:Summary())
    self.UI:AddButton(systemTab, "Проверить известные Remotes", function()
        self.NetworkStatus:Set(self.Network:Summary())
    end)
    self.UI:AddText(systemTab, "Безопасность", "Античита в MM2 не найдено (проверено по 9 хабам), но Roblox-античит на уровне клиента зависит от экзекьютора. Не провоцируй игроков на репорты.")

    self.UI:AddHeading(systemTab, "Диагностика")
    self.UI:AddText(systemTab, "Сборка " .. self.Config.Version,
        "CALM: печатается только номер версии, рандомный ключ реестра, скрытый маунт, ноль хуков. 40+ функций.")
end

---------------------------------------------------------------------
-- Helpers
---------------------------------------------------------------------

function Features:UpdateRoleStatus()
    local murderer = self.Roles.FindByRole("Murderer")
    local sheriff = self.Roles.FindByRole("Sheriff")
    local hero = self.Roles.FindByRole("Hero")
    local parts = {}
    parts[#parts + 1] = "маньяк: " .. (#murderer > 0 and table.concat(murderer, ", ") or "неизвестен")
    parts[#parts + 1] = "шериф: " .. (#sheriff > 0 and table.concat(sheriff, ", ") or "неизвестен")
    if #hero > 0 then parts[#parts + 1] = "герой: " .. table.concat(hero, ", ") end
    if self.RoleStatus then
        self.RoleStatus:Set(table.concat(parts, " • "))
    end
end

function Features:GlideToPlayer(playerName)
    local target = Players:FindFirstChild(playerName)
    local root = target and target.Character and target.Character:FindFirstChild("HumanoidRootPart")
    if root and self.Stealth and self.Stealth.GlideTo then
        task.spawn(function()
            self.Stealth.GlideTo(root.Position, {})
        end)
        return true
    end
    return false
end

---------------------------------------------------------------------
-- Monitor loop: statuses + gun grabber
---------------------------------------------------------------------

function Features:Start()
    if self.Running then return end
    self.Running = true
    self.World.Start()

    task.spawn(function()
        task.wait(0.6)
        pcall(function() self.Roles.Refresh() end)
        while self.Running and self.Alive() do
            pcall(function() self:UpdateRoleStatus() end)
            if self.FarmStatus then pcall(function() self.FarmStatus:Set(self.Farm.Summary()) end) end
            if self.CombatStatus and self.Combat.Status and self.Combat.Status ~= "" then
                pcall(function() self.CombatStatus:Set(self.Combat.Status) end)
            end

            -- Gun grabber: non-murderer glides to a dropped gun, then back.
            local settings = self.Config.Settings
            if settings.GunGrabber and not self.Roles.LocalIsMurderer() then
                local drop = self.World.GetGunDrop()
                if drop and os.clock() - self.LastGrabAt > 4 then
                    self.LastGrabAt = os.clock()
                    local myRoot = localPlayer.Character and localPlayer.Character:FindFirstChild("HumanoidRootPart")
                    if myRoot and self.Stealth and self.Stealth.GlideTo then
                        task.spawn(function()
                            local before = myRoot.CFrame
                            self.Stealth.GlideTo(drop.Position, { Speed = 70 })
                            -- wait for pickup confirmation (drop disappears)
                            local waited = 0
                            while drop.Parent and waited < 2.5 do
                                waited = waited + task.wait(0.25)
                            end
                            if not drop.Parent then
                                if self.Stealth.Registry and self.Stealth.Registry.NotifyGrab then
                                    -- no-op hook for future notifications
                                end
                                task.wait(0.6)
                                self.Stealth.GlideTo(before.Position, { Speed = 70 })
                            end
                        end)
                    end
                end
            end

            task.wait(1.2)
        end
    end)
end

function Features:Destroy()
    self.Running = false
    pcall(function() self.ESP.Destroy() end)
    pcall(function() self.Farm.Destroy() end)
    pcall(function() self.Combat.Destroy() end)
    pcall(function() self.Movement.Destroy() end)
    pcall(function() self.Visuals.Destroy() end)
    pcall(function() self.Roles.Shutdown() end)
    pcall(function() self.World.Destroy() end)
end

return Features
